package org.opensmartisanos.ui.widget;
import android.content.Context;import android.content.res.TypedArray;import android.graphics.drawable.Drawable;import android.util.AttributeSet;import android.view.LayoutInflater;import android.widget.ImageView;import android.widget.LinearLayout;import org.opensmartisanos.ui.R;
public class SmartisanButtonGroup extends LinearLayout { private int count;private boolean gap,supportLayout;private SmartisanShadowButton[] buttons;private final LinearLayout container;private final ImageView shadow;public SmartisanButtonGroup(Context c){this(c,null);}public SmartisanButtonGroup(Context c,AttributeSet a){this(c,a,0);}public SmartisanButtonGroup(Context c,AttributeSet a,int s){super(c,a,s);setOrientation(VERTICAL);LayoutInflater.from(c).inflate(R.layout.smartisan_rom_button_group_layout,this,true);container=findViewById(R.id.smartisan_rom_ll_group_button_container);shadow=findViewById(R.id.smartisan_rom_smartisan_iv_btn_group_shadow);TypedArray v=c.obtainStyledAttributes(a,R.styleable.SmartisanButtonGroup,s,0);count=v.getInt(R.styleable.SmartisanButtonGroup_buttonCount,3);gap=v.getBoolean(R.styleable.SmartisanButtonGroup_hasButtonGap,true);supportLayout=v.getBoolean(R.styleable.SmartisanButtonGroup_supportLayout,true);v.recycle();verify(count);setup();}private void verify(int v){if(v<=0)throw new IllegalArgumentException("count must be positive: "+v);}private void setup(){container.removeAllViews();int pad=getResources().getDimensionPixelSize(R.dimen.smartisan_rom_button_group_left_right_padding);container.setPadding(gap?0:pad,0,gap?0:pad,0);buttons=new SmartisanShadowButton[count];int overlap=getResources().getDimensionPixelSize(R.dimen.smartisan_rom_button_group_btn_gap);for(int i=0;i<count;i++){SmartisanShadowButton b=new SmartisanShadowButton(getContext(),null,0,R.style.Widget_SmartisanUi_ShadowButton_Small);LayoutParams p=new LayoutParams(0,android.view.ViewGroup.LayoutParams.WRAP_CONTENT,1);if(gap&&i>0)p.leftMargin=-overlap;b.setLayoutParams(p);if(!gap&&count>1)b.setBackgroundResource(i==0?R.drawable.smartisan_rom_selector_small_btn_filter_left:i==count-1?R.drawable.smartisan_rom_selector_small_btn_filter_right:R.drawable.smartisan_rom_selector_small_btn_filter_middle);else b.updateBackgroundStyle(SmartisanShadowButton.SmallButtonStyle.STANDARD);b.setSingleLine();buttons[i]=b;container.addView(b);}}public void setButtonCount(int value,boolean hasGap){verify(value);count=value;gap=hasGap;setup();}public int getButtonCount(){return count;}public void setButtonText(int i,CharSequence s){buttons[i].setText(s);}public void setButtonText(int i,int r){setButtonText(i,getResources().getString(r));}public SmartisanShadowButton getButton(int i){return buttons[i];}public void setButtonActivated(int selected){for(int i=0;i<count;i++)buttons[i].setActivated(i==selected);}public void setButtonGroupBackground(int r){container.setBackgroundResource(r);}public void setButtonGroupBackground(Drawable d){container.setBackground(d);}public void setButtonGroupBackgroundColor(int c){container.setBackgroundColor(c);}public void setButtonGroupShadowVisibility(boolean v){shadow.setVisibility(v?VISIBLE:GONE);}public void setShadowDrawable(int r){shadow.setBackgroundResource(r);}}
